28. 
29.     protected override async Task OnAfterRenderAsync(bool firstRender)
30.     {
31.         if (firstRender)
32.         {
33.             _interop = new NotepadInterop(JS);
34.             await _interop.InitializeAsync();
35. 
36.             var saved = await _interop.LoadAsync();
37.             if (!string.IsNullOrEmpty(saved))
38.             {
39.                 _content = saved;
40.                 StateHasChanged();
41.             }
42. 
43.             _autoSaveTimer = new Timer(AutoSaveCallback, null, TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));
44.         }
45.     }
46. 
47.     private async Task OnContentChanged()
48.     {
49.         if (_interop is not null)
50.         {
51.             _isDirty = true;
52.             await _interop.MarkDirtyAsync();
53.         }
54.     }
55. 
