87.     {
88.         if (_interop is not null)
89.         {
90.             _content = string.Empty;
91.             await _interop.ClearAsync();
92.             _lastSavedAt = null;
93.             _isDirty = false;
94.         }
95.     }
96. 
97.     public async ValueTask DisposeAsync()
98.     {
99.         _autoSaveTimer?.Dispose();
100. 
